mapper.select:
/* LeaveRemnantCoverMapper.selectRemnantDeductibleGrants */
SELECT
      G.GRANT_ID      AS grantId
    , G.LEAVE_CD      AS leaveCd
    , G.GRANT_DAYS    AS grantDays
    , G.USED_DAYS     AS usedDays
    , G.AVAIL_TO_DATE AS availToDate
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD = #{cmpnyCd}
   AND G.USER_CD  = #{userCd}
   AND G.LEAVE_CD IN
   #{cd}
   AND G.DEL_YN   = 'N'
   AND G.STATUS   = 'ACTIVE'
   AND G.AVAIL_FROM_DATE <= #{workYmd}
   AND G.AVAIL_TO_DATE   >= #{workYmd}
   AND (G.GRANT_DAYS - G.USED_DAYS) > 0
 ORDER BY G.AVAIL_TO_DATE ASC, G.GRANT_DATE ASC, G.GRANT_ID ASC
 FOR UPDATE

/* LeaveRemnantCoverMapper.countUpcomingLeaveUse */
SELECT COUNT(*)
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD     = #{cmpnyCd}
   AND U.USER_CD      = #{userCd}
   AND U.LEAVE_STATUS = 'CONFIRMED'
   AND U.DEL_YN       = 'N'
   AND U.START_DATE  >= #{fromYmd}
   AND U.LEAVE_CD IN
   #{cd}

mapper.insert:
/* LeaveRemnantCoverMapper.insertLeaveUse */
INSERT INTO TB_USER_LEAVE_USE (
      LEAVE_ID
    , CMPNY_CD
    , SITE_CD
    , USER_CD
    , LEAVE_CD
    , REQ_ID
    , GRANT_ID
    , START_DATE
    , START_TIME
    , END_DATE
    , END_TIME
    , USE_UNIT_TYPE
    , LEAVE_DAYS
    , LEAVE_MINUTES
    , LEAVE_REASON
    , LEAVE_STATUS
    , DEL_YN
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
      #{leaveId}
    , #{cmpnyCd}
    , #{siteCd}
    , #{userCd}
    , #{leaveCd}
    , #{reqId}
    , #{grantId}
    , #{startDate}
    , #{startTime}
    , #{endDate}
    , #{endTime}
    , #{useUnitType}
    , #{leaveDays}
    , #{leaveMinutes}
    , #{leaveReason}
    , #{leaveStatus}
    , 'N'
    , #{insertNo}
    , NOW()
)

/* LeaveRemnantCoverMapper.insertCover */
INSERT INTO TB_LEAVE_REMNANT_COVER (
      COVER_ID
    , CMPNY_CD
    , SITE_CD
    , USER_CD
    , REQ_ID
    , WORK_YMD
    , USE_UNIT_TYPE
    , CHARGE_DAYS
    , REMNANT_DAYS
    , COVER_DAYS
    , COVER_MINUTES
    , CONV_MINUTES
    , COVER_STATUS
    , DEL_YN
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
      #{coverId}
    , #{cmpnyCd}
    , #{siteCd}
    , #{userCd}
    , #{reqId}
    , #{workYmd}
    , #{useUnitType}
    , #{chargeDays}
    , #{remnantDays}
    , #{coverDays}
    , #{coverMinutes}
    , #{convMinutes}
    , 'ACTIVE'
    , 'N'
    , #{insertNo}
    , NOW()
)

mapper.update:
/* LeaveRemnantCoverMapper.recomputeGrantUsedDays */
UPDATE TB_USER_LEAVE_GRANT G
   SET G.USED_DAYS = IFNULL((
           SELECT SUM(U.LEAVE_DAYS)
             FROM TB_USER_LEAVE_USE U
            WHERE U.CMPNY_CD     = G.CMPNY_CD
              AND U.GRANT_ID     = G.GRANT_ID
              AND U.LEAVE_STATUS = 'CONFIRMED'
              AND U.DEL_YN       = 'N'
       ), 0)
     , G.UPDATE_NO   = #{updateNo}
     , G.UPDATE_DATE = NOW()
 WHERE G.CMPNY_CD = #{cmpnyCd}
   AND G.GRANT_ID = #{grantId}

/* LeaveRemnantCoverMapper.updateCoverReclaim */
UPDATE TB_LEAVE_REMNANT_COVER
   SET COVER_DAYS    = #{coverDays}
     , COVER_MINUTES = #{coverMinutes}

     , COVER_STATUS  = 'RECLAIMED'
     , RECLAIM_DATE  = NOW()

     , UPDATE_NO     = #{updateNo}
     , UPDATE_DATE   = NOW()
 WHERE CMPNY_CD = #{cmpnyCd}
   AND COVER_ID = #{coverId}
   AND DEL_YN   = 'N'

/* LeaveRemnantCoverMapper.cancelCoversByReqId */
UPDATE TB_LEAVE_REMNANT_COVER
   SET COVER_STATUS = 'CANCELLED'
     , UPDATE_NO    = #{updateNo}
     , UPDATE_DATE  = NOW()
 WHERE CMPNY_CD     = #{cmpnyCd}
   AND REQ_ID       = #{reqId}
   AND COVER_STATUS = 'ACTIVE'
   AND DEL_YN       = 'N'
